"""run.py —— 单文件自释放入口。
双击运行后把内嵌的全部程序源文件释放到本文件所在目录（core/、ui/ 及根目录 .py）。
已存在的文件跳过、不覆盖（避免破坏用户可能已有的本地修改）。
释放完成后双击 scanner_gui.py 即可运行主程序。
"""
from __future__ import annotations

import base64
import os

# 内嵌文件：(相对路径, base64 内容)
_FILES = [
    ('scanner_gui.py', ''),
    ('db_view.py', ''),
    ('core/__init__.py', ''),
    ('core/analysis.py', ''),
    ('core/config.py', ''),
    ('core/exporter.py', ''),
    ('core/maintainer.py', ''),
    ('core/paths.py', ''),
    ('core/repo.py', ''),
    ('core/scanner.py', ''),
    ('ui/__init__.py', ''),
    ('ui/main_window.py', ''),
    ('ui/task_center.py', ''),
    ('ui/widgets.py', ''),
]


def _release(target_dir):
    created = []
    for rel, b64 in _FILES:
        dest = os.path.join(target_dir, rel)
        parent = os.path.dirname(dest)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent, exist_ok=True)
        # 已存在则跳过，避免覆盖用户可能已有的本地修改
        if os.path.exists(dest):
            continue
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64))
        created.append(rel)
    return created


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    created = _release(here)
    if created:
        print("[release] 已释放 %d 个文件到：%s" % (len(created), here))
        for r in created:
            print("  + " + r)
    else:
        print("[release] 所有程序文件已存在，无需释放：%s" % here)
        print("双击 scanner_gui.py 即可运行主程序。")


if __name__ == "__main__":
    main()
